(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.02-t*0.2)*15;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.022+t*0.35)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.5)*8 + Math.cos((y+w1y)*0.03+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.028+t*0.45)*7 + Math.sin((x+w1x)*0.032-t*0.55)*5;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [120+Math.sin(t*0.6)*100, 60+Math.cos(t*0.4)*50, 0.07, 2.0],
    [360+Math.cos(t*0.5)*100, 180+Math.sin(t*0.7)*50, 0.09, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3],
    [80+Math.cos(t*0.8+1)*80, 200+Math.sin(t*0.6+3)*60, 0.11, 1.5],
    [400+Math.sin(t*0.4+4)*90, 40+Math.cos(t*0.9+2)*70, 0.065, 2.6],
    [240+Math.cos(t*0.35+5)*120, 220+Math.sin(t*0.55)*80, 0.08, 1.9],
    [180+Math.sin(t*0.45+3)*110, 100+Math.cos(t*0.65+2)*65, 0.075, 2.1],
    [300+Math.cos(t*0.55+1)*95, 150+Math.sin(t*0.75+4)*55, 0.085, 1.8],
    [60+Math.sin(t*0.7+5)*70, 130+Math.cos(t*0.5+3)*80, 0.06, 2.4],
    [420+Math.cos(t*0.38+2)*85, 90+Math.sin(t*0.82+1)*75, 0.095, 1.6]
  ];
  let aS = 0, iS = 0, aS2 = 0, iS2 = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS2 += Math.sin(d*f*1.3 - t*sp*0.8 + 2.0);
    iS2 += Math.sin(d*f*0.5 + t*sp*0.9 + 3.0);
  }
  const act = aS/10, inh = iS/10, act2 = aS2/10, inh2 = iS2/10;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.8) + Math.sin(sx*0.028-sy*0.038+t*1.1) + Math.sin(sx*0.045+sy*0.01-t*0.7))/3
    + Math.sin((sx+sy)*0.11+t*2.5)*0.15 + Math.sin((sx-sy)*0.09-t*2)*0.15
    + Math.sin(sx*0.08)*Math.sin(sy*0.08)*0.1;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3-t*1.5) + Math.sin(dist*0.035+ang*4-t*1.2) + Math.sin(dist*0.06-ang*2+t*0.8))*0.3;
  const fine = Math.sin(sx*0.2+Math.sin(sy*0.15+t)*3)*Math.sin(sy*0.2+Math.cos(sx*0.18-t)*3)*0.15;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral)*2.2);
  const reaction2 = Math.tanh((act2 - inh2*0.7 + fine*0.5)*1.8);
  const combined = reaction*0.7 + reaction2*0.3;
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.09+t)*0.5 + Math.sin((sx*2-sy)*0.07-t*0.7)*0.3)*1.5)*0.25;
  const blend = combined*0.7 + cell*0.3, v = blend*0.5+0.5;
  const pal = [
    [5,12,55],[10,35,85],[12,60,105],[15,95,120],[20,135,130],
    [80,165,120],[170,185,80],[220,195,55],[235,150,60],
    [220,95,55],[185,55,60],[140,30,65],[85,18,55],[40,12,50],[5,12,55]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(combined*Math.PI)*0.25;
  const edge = Math.abs(combined)>0.65 ? 1.12 + Math.abs(combined)*0.08 : 1.0;
  const glow = Math.max(0, 1.0 - Math.abs(combined)*1.5)*0.15;
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)/400*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40)*vig)|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*60)*vig)|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)*vig)|0
  ];
}
